/*
 * prog55_connected_components.c
 *
 * The original binary implements a very small graph library (max 8 vertices)
 * that reads a graph from the command line, checks the input, builds an
 * adjacency matrix and prints the connected components.
 *
 * The observable behaviour (stdout and exit code) is reproduced exactly.
 *
 * Usage:
 *   prog55_connected_components N M u1 v1 u2 v2 ... uM vM
 *
 *   N – number of vertices (0 … 7)
 *   M – number of edges    (0 … 7)
 *   ui vi – the two endpoints of edge i (0‑based, must be < N)
 *
 * Output format (one line per component):
 *   <component_index>: {v0,v1,...,vk}
 *
 * If any argument is out of range, missing, or the number of arguments does
 * not match 2·M, the program prints the single line
 *
 *   INVALID_INPUT
 *
 * and returns 1.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8                     /* maximum number of vertices */

static int adj[MAXV][MAXV];         /* adjacency matrix */
static int visited[MAXV];          /* visited flag for each vertex */
static int queue_[MAXV];           /* simple FIFO queue for BFS */

/* --------------------------------------------------------------------- */
static int read_int(const char *s, int *out)
{
    char *endptr;
    long v = strtol(s, &endptr, 10);
    if (*endptr != '\0')          /* not a pure integer */
        return 0;
    *out = (int)v;
    return 1;
}

/* --------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    int n, m;                     /* number of vertices and edges */
    int i, u, v;
    int comp_idx = 0;             /* component counter */

    /* ---------- argument count check --------------------------------- */
    if (argc < 3) {               /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- read N and M ------------------------------------------ */
    if (!read_int(argv[1], &n) || !read_int(argv[2], &m)) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- range checks ------------------------------------------ */
    if (n < 0 || n > MAXV - 1 || m < 0 || m > MAXV - 1) {
        puts("INVALID_INPUT");
        return 1;
    }

    if (argc != 3 + 2 * m) {      /* exactly 2 numbers per edge */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- initialise adjacency matrix --------------------------- */
    memset(adj, 0, sizeof(adj));
    memset(visited, 0, sizeof(visited));

    /* ---------- read edges -------------------------------------------- */
    for (i = 0; i < m; ++i) {
        if (!read_int(argv[3 + 2 * i],     &u) ||
            !read_int(argv[3 + 2 * i + 1], &v)) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = adj[v][u] = 1;   /* undirected edge */
    }

    /* ---------- BFS to find connected components ---------------------- */
    for (i = 0; i < n; ++i) {
        if (visited[i])
            continue;               /* already part of a component */

        /* start a new component */
        printf("%d:", comp_idx++);
        printf(" {");

        /* BFS queue initialisation */
        int qhead = 0, qtail = 0;
        queue_[qtail++] = i;
        visited[i] = 1;

        int first_in_component = 1;

        while (qhead < qtail) {
            int cur = queue_[qhead++];
            /* print the vertex (with commas between them) */
            if (!first_in_component)
                putchar(',');
            printf("%d", cur);
            first_in_component = 0;

            /* enqueue all unvisited neighbours */
            for (v = 0; v < n; ++v) {
                if (adj[cur][v] && !visited[v]) {
                    visited[v] = 1;
                    queue_[qtail++] = v;
                }
            }
        }

        putchar('}');
        putchar('\n');
    }

    return 0;
}
